// What ties worfy to the Codex it pins (@openai/codex in package.json; worfy-multi-vendor ticket 30), as
// test/contract/sdk-compat.test.ts does for the Agent SDK:
//   - the recorded messages of the live app-server (test/fixtures/codex-messages/) were recorded with that
//     Codex, as their manifest.json and the `cliVersion` of every recorded thread say, and node_modules has
//     that Codex. No recordings, or recordings of another version, is red;
//   - every recorded message passes the JSON Schema of the pinned Codex
//     (src/main/vendors/codex/protocol/json/, generated by scripts/codex-protocol.mjs), as Codex generated
//     it: the schemas leave objects open, so a field they do not name passes;
//   - the fake app-server (test/fixtures/codex-app-server/fake-app-server.mjs) plays only kinds of messages
//     and key paths the live app-server sent: every step of its scripts (test/fixtures/codex-scripts/)
//     against the recordings (kinds and key paths: kindOf and shapeOf of scripts/codex-capture.mjs), so
//     contract tests on the fake do not pass on an invented form. A shape the recordings lack passes only
//     with an exception that names why (EXCEPTIONS);
//   - the recorded hook inputs (hooks/<event>.jsonl) have PreToolUse, Stop and SubagentStop, and every
//     SubagentStop input names its agent_type: the fake of hooks (worfy-multi-vendor ticket 44) plays them.
// Never starts Codex: the recordings are taken by the owner, with their ChatGPT login.
//
// How the pinned Codex changes, in a PR of its own:
//   1. raise `@openai/codex` in package.json (an exact version) and run pnpm install;
//   2. `node scripts/codex-protocol.mjs` — new types and JSON Schema; the fake's scripts must still pass
//      them (test/contract/codex-fake.test.ts);
//   3. the owner runs `node scripts/codex-capture.mjs --use-my-login` — new recordings and manifest here;
//   4. this test, green. A raised version without new recordings is red here.
//
// WORFY_CODEX_RECORDINGS names another recordings folder: only for proving the control cases of the ticket
// on synthetic recordings outside the repository; synthetic recordings are never committed.
import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { dirname, join } from 'node:path'
import { pathToFileURL } from 'node:url'
import { describe, expect, it } from 'vitest'
import { FAKE_SCRIPTS } from '../../src/main/vendors/codex/launch'
import { CODEX_SCHEMA_BUNDLE, codexAjv } from '../../src/main/vendors/codex/schema'

const ROOT = join(import.meta.dirname, '..', '..')
const DEFAULT_RECORDINGS = join(ROOT, 'test', 'fixtures', 'codex-messages')
const RECORDINGS = process.env.WORFY_CODEX_RECORDINGS || DEFAULT_RECORDINGS
const SCRIPTS = join(ROOT, FAKE_SCRIPTS)
const BUNDLE = join(ROOT, 'src', 'main', 'vendors', 'codex', 'protocol', 'json', CODEX_SCHEMA_BUNDLE)
const PACKAGE = '@openai/codex'

const CAPTURE = 'node scripts/codex-capture.mjs --use-my-login'

/** A step of a fake script or a recording, in the form of the fake's scripts (scripts/codex-capture.mjs). */
interface Step {
  expect?: string
  notify?: string
  request?: string
  params?: unknown
  result?: unknown
  error?: unknown
  answer?: unknown
  answerError?: unknown
}
interface Played {
  /** `<file>:<line>`. */
  where: string
  step: Step
}
type Shape = Record<string, string[]>
/** What replaces a value that names the owner or the run in the recordings (scripts/codex-capture.mjs). */
interface Replacement {
  from: string
  to: string
  what: string
  name?: boolean
}
interface CodexCapture {
  kindOf(step: Step): string
  bodyOf(step: Step): unknown
  shapeOf(value: unknown): Shape
  readSteps(file: string, name?: string): Played[]
  scrub<T>(value: T, replacements: readonly Replacement[]): T
  leftovers(text: string, replacements: readonly Replacement[]): string[]
  hostReplacements(host: string): Replacement[]
  identifierReplacements(steps: readonly unknown[]): Replacement[]
  replacementsOf(run: { project: string; codexHome: string; work: string; home: string; host: string; steps: readonly unknown[]; secrets: readonly Replacement[] }): Replacement[]
  main(argv: string[]): Promise<number>
}
const capture = (await import(pathToFileURL(join(ROOT, 'scripts', 'codex-capture.mjs')).href)) as CodexCapture
const { kindOf, bodyOf, shapeOf, readSteps } = capture

interface Manifest {
  codex?: unknown
}
interface Recordings {
  folder: string
  manifest: Manifest | null
  steps: Played[]
}

function readRecordings(folder: string): Recordings {
  const files = existsSync(folder)
    ? readdirSync(folder)
        .filter((name) => name.endsWith('.jsonl'))
        .sort()
    : []
  const manifestFile = join(folder, 'manifest.json')
  return {
    folder,
    manifest: existsSync(manifestFile) ? (JSON.parse(readFileSync(manifestFile, 'utf8')) as Manifest) : null,
    steps: files.flatMap((name) => readSteps(join(folder, name), name)),
  }
}

const pinnedCodex = (): string => (JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8')) as { dependencies: Record<string, string> }).dependencies[PACKAGE] ?? 'none'

const installedCodex = (): string => {
  const launcher = createRequire(join(ROOT, 'package.json')).resolve(`${PACKAGE}/bin/codex.js`)
  return (JSON.parse(readFileSync(join(dirname(launcher), '..', 'package.json'), 'utf8')) as { version: string }).version
}

/** Every value of a `cliVersion` key inside `value`: the Codex version a recorded thread names. */
function cliVersions(value: unknown, found: unknown[] = []): unknown[] {
  if (Array.isArray(value)) for (const item of value) cliVersions(item, found)
  else if (value !== null && typeof value === 'object') {
    for (const [key, child] of Object.entries(value)) {
      if (key === 'cliVersion') found.push(child)
      else cliVersions(child, found)
    }
  }
  return found
}

/**
 * What is wrong with the recordings as recordings of the Codex `pinned`, with `installed` in node_modules:
 * empty when they are there, of that version, and node_modules has it too.
 */
function versionProblems(recordings: Recordings, pinned: string, installed: string): string[] {
  const where = recordings.folder === DEFAULT_RECORDINGS ? 'test/fixtures/codex-messages' : recordings.folder
  if (recordings.manifest === null || recordings.steps.length === 0) {
    return [`no recordings of Codex ${pinned} in ${where} (a manifest.json and *.jsonl): the owner records them with \`${CAPTURE}\` (worfy-multi-vendor ticket 30, done by hand)`]
  }
  const problems: string[] = []
  const recorded = recordings.manifest.codex
  if (recorded !== pinned) problems.push(`${where}/manifest.json: recorded with Codex ${String(recorded)}, package.json pins ${pinned}; the owner records them again with \`${CAPTURE}\``)
  if (installed !== pinned) problems.push(`node_modules has ${PACKAGE} ${installed}, package.json pins ${pinned}; run pnpm install`)
  const threads = recordings.steps.flatMap(({ where: at, step }) => cliVersions(bodyOf(step)).map((version) => ({ at, version })))
  if (threads.length === 0) problems.push(`${where}: no recorded thread names its cliVersion`)
  for (const { at, version } of threads) if (version !== pinned) problems.push(`${at}: a thread of Codex ${String(version)}, package.json pins ${pinned}`)
  return problems
}

// --- The recorded hook inputs, for the fake of hooks (worfy-multi-vendor ticket 44) ----------------

/** The hook events whose inputs the recordings must have. */
const HOOK_EVENTS = ['PreToolUse', 'Stop', 'SubagentStop'] as const

/** The inputs of `hooks/<event>.jsonl` in `folder` for each event of HOOK_EVENTS: null for no file, a line that is not JSON as a string. */
function readHooks(folder: string): Record<string, unknown[] | null> {
  return Object.fromEntries(
    HOOK_EVENTS.map((event) => {
      const file = join(folder, 'hooks', `${event}.jsonl`)
      if (!existsSync(file)) return [event, null]
      const lines = readFileSync(file, 'utf8')
        .split(/\r?\n/)
        .filter((line) => line.trim() !== '')
      return [
        event,
        lines.map((line): unknown => {
          try {
            return JSON.parse(line) as unknown
          } catch {
            return line
          }
        }),
      ]
    }),
  )
}

/**
 * What is wrong with the recorded hook inputs: each event of HOOK_EVENTS has at least one input, every
 * input is an object of that event, and every SubagentStop input names the Subagent's agent_type.
 */
function hookProblems(hooks: Record<string, unknown[] | null>): string[] {
  return HOOK_EVENTS.flatMap((event) => {
    const inputs = hooks[event] ?? null
    if (inputs === null || inputs.length === 0) return [`hooks/${event}.jsonl: no recorded input of ${event}`]
    return inputs.flatMap((input, index) => {
      const where = `hooks/${event}.jsonl:${index + 1}`
      if (!isSchema(input) || input.hook_event_name !== event) return [`${where}: not an input of ${event}`]
      if (event === 'SubagentStop' && (typeof input.agent_type !== 'string' || input.agent_type === '')) return [`${where}: no agent_type`]
      return []
    })
  })
}

// --- The recordings against the JSON Schema of the pinned Codex ------------------------------------

type Schema = Record<string, unknown>
const isSchema = (value: unknown): value is Schema => typeof value === 'object' && value !== null && !Array.isArray(value)

interface Bundle {
  definitions: Record<string, Schema> & Record<'ClientRequest' | 'ClientNotification' | 'ServerNotification' | 'ServerRequest', Schema>
}

/** The method names of a oneOf of messages (ClientRequest, ServerNotification…) with the schema of each. */
function methodsOf(union: Schema): Map<string, Schema> {
  const methods = new Map<string, Schema>()
  for (const branch of union.oneOf as Schema[]) {
    const [method] = ((branch.properties as Schema).method as Schema).enum as [string]
    methods.set(method, branch)
  }
  return methods
}

/** The first `$ref` inside `schema`, or undefined. */
function firstRef(schema: unknown): string | undefined {
  if (Array.isArray(schema)) return schema.map(firstRef).find((ref) => ref !== undefined)
  if (!isSchema(schema)) return undefined
  if (typeof schema.$ref === 'string') return schema.$ref
  return Object.values(schema).map(firstRef).find((ref) => ref !== undefined)
}

/** Responses whose request has no params definition to name them after. */
const RESPONSES: Readonly<Record<string, string>> = { 'account/logout': 'v2/LogoutAccountResponse' }

/**
 * The checker of recorded steps: what in each step the generated JSON Schema refuses, as `<where>: …`.
 * A request of either side is checked with its params, its answer against the response named after
 * them (`v2/ThreadStartParams` → `v2/ThreadStartResponse`), a refusal as a JSON-RPC error.
 */
function schemaChecker(): (played: readonly Played[]) => string[] {
  const bundle = JSON.parse(readFileSync(BUNDLE, 'utf8')) as Bundle
  const ajv = codexAjv()
  ajv.addSchema(bundle, 'codex')
  const validators = new Map<string, ReturnType<typeof ajv.compile>>()
  const has = (name: string) => (name.startsWith('v2/') ? isSchema(bundle.definitions.v2?.[name.slice(3)]) : isSchema(bundle.definitions[name]))
  const check = (name: string, value: unknown): string[] => {
    let validate = validators.get(name)
    if (validate === undefined) {
      const found = ajv.getSchema(`codex#/definitions/${name}`)
      if (found === undefined) return [`no ${name} in the schema`]
      validate = found
      validators.set(name, validate)
    }
    return validate(value) ? [] : (validate.errors ?? []).slice(0, 5).map((error) => `${name}${error.instancePath} ${error.message ?? ''} ${JSON.stringify(error.params)}`)
  }
  const unions = {
    request: methodsOf(bundle.definitions.ClientRequest),
    clientNotification: methodsOf(bundle.definitions.ClientNotification),
    notification: methodsOf(bundle.definitions.ServerNotification),
    serverRequest: methodsOf(bundle.definitions.ServerRequest),
  }
  const paramsOf = (union: Map<string, Schema>, method: string): string | undefined => firstRef((union.get(method)?.properties as Schema | undefined)?.params)?.replace('#/definitions/', '')
  const responseOf = (union: Map<string, Schema>, method: string): string | undefined => {
    const named = RESPONSES[method] ?? paramsOf(union, method)?.replace(/Params$/, 'Response')
    return named !== undefined && has(named) ? named : undefined
  }
  const definitionOf = { ClientRequest: unions.request, ClientNotification: unions.clientNotification, ServerNotification: unions.notification, ServerRequest: unions.serverRequest }
  /**
   * A message of `unionName`: its params against the definition of its method's params (so the errors
   * name only that method), or, for a method without one or a message without params, the whole
   * message against the union.
   */
  const message = (unionName: keyof typeof definitionOf, method: string, params: unknown, id?: number) => {
    const definition = paramsOf(definitionOf[unionName], method)
    return definition === undefined || params === undefined ? check(unionName, { ...(id === undefined ? {} : { id }), method, ...(params === undefined ? {} : { params }) }) : check(definition, params)
  }
  const answered = (union: Map<string, Schema>, method: string, result: unknown, error: unknown): string[] => {
    if (error !== undefined) return check('JSONRPCErrorError', error)
    if (result === undefined) return []
    const response = responseOf(union, method)
    return response === undefined ? [`no response schema for ${method}`] : check(response, result)
  }
  return (played) =>
    played.flatMap(({ where, step }) => {
      const problems: string[] = []
      if (step.notify !== undefined) {
        if (!unions.notification.has(step.notify)) problems.push(`${step.notify} is not a notification of the server`)
        else problems.push(...message('ServerNotification', step.notify, step.params))
      } else if (step.request !== undefined) {
        if (!unions.serverRequest.has(step.request)) problems.push(`${step.request} is not a request of the server`)
        else problems.push(...message('ServerRequest', step.request, step.params, 0), ...answered(unions.serverRequest, step.request, step.answer, step.answerError))
      } else if (step.expect !== undefined && step.result === undefined && step.error === undefined) {
        if (!unions.clientNotification.has(step.expect)) problems.push(`${step.expect} is not a notification of the client`)
        else problems.push(...message('ClientNotification', step.expect, step.params))
      } else if (step.expect !== undefined) {
        if (!unions.request.has(step.expect)) problems.push(`${step.expect} is not a request of the client`)
        else {
          // A fake script names no params of worfy's request; a recording names every one.
          if ('params' in step) problems.push(...message('ClientRequest', step.expect, step.params, 0))
          problems.push(...answered(unions.request, step.expect, step.result, step.error))
        }
      } else problems.push('a step has one of "expect", "notify" or "request"')
      return problems.map((problem) => `${where}: ${problem}`)
    })
}

let checker: ((played: readonly Played[]) => string[]) | undefined
const schemaProblems = (played: readonly Played[]): string[] => (checker ??= schemaChecker())(played)

// --- The fake's scripts against the recordings -------------------------------------------------------

/** The shapes of many steps, merged by kind: `{ kind: { path: [types] } }`. */
function shapesByKind(played: readonly Played[]): Record<string, Shape> {
  const kinds: Record<string, Shape> = {}
  for (const { step } of played) {
    const kind = (kinds[kindOf(step)] ??= {})
    for (const [path, types] of Object.entries(shapeOf(bodyOf(step)))) kind[path] = [...new Set([...(kind[path] ?? []), ...types])].sort()
  }
  return kinds
}

/**
 * A shape the fake plays that no recording has, and why it may: the whole kind (no `path`), or a key
 * path and everything under it. Added with the recordings, each with the reason the live run could not
 * produce it; the suite fails an exception no script needs any more.
 */
interface Exception {
  kind: string
  path?: string
  reason: string
}

// The recordings of Codex 0.166.0 (plan Plus, 2026-11-03) lack these; each is a case the live run did not
// reach, which the JSON Schema of the pinned Codex has (the suite checks every fake step against it too).
const EXCEPTIONS: readonly Exception[] = [
  // Reasoning items: the run asked for summaries (model_reasoning_summary = "detailed"), and no turn of it
  // gave a reasoning item or a summary delta.
  { kind: 'notify item/started', path: 'item(reasoning)', reason: 'no turn of the live run gave a reasoning item' },
  { kind: 'notify item/completed', path: 'item(reasoning)', reason: 'no turn of the live run gave a reasoning item' },
  { kind: 'notify item/reasoning/summaryTextDelta', reason: 'no turn of the live run gave a reasoning summary' },
  { kind: 'result thread/read', path: 'thread.turns[].items[](reasoning)', reason: 'the thread read in the live run had no reasoning item' },
  // The plan: in the live run the model answered that update_plan was unavailable (turn.jsonl:72).
  { kind: 'notify item/completed', path: 'item(plan)', reason: 'update_plan was unavailable to the model in the live run' },
  { kind: 'notify turn/plan/updated', reason: 'update_plan was unavailable to the model in the live run' },
  // The approvals of the live run were asked under the untrusted policy, which gives no reason; Codex gives
  // one when the model asks to leave the sandbox (the schema: "e.g. request for network access").
  { kind: 'request item/commandExecution/requestApproval', path: 'reason', reason: 'the live run asked no approval to leave the sandbox' },
  // The live MCP tool that failed returned its error as a result (mcp.jsonl, tool `fail`: error null);
  // `error` is a call that never reached the tool, as a server that is not running.
  { kind: 'notify item/completed', path: 'item(mcpToolCall).error.message', reason: 'the live run had no MCP call that failed before the tool' },
  // Codex compacted even the empty thread of the live run (compact.jsonl:16, result {}): it refused none.
  { kind: 'error thread/compact/start', reason: 'Codex refused no compaction in the live run' },
  { kind: 'notify skills/changed', reason: 'the live run got no skills/changed within 15 s of adding a skill' },
  // The capture sends the skill as text ($name), worfy as a skill item of turn/start.
  { kind: 'result thread/read', path: 'thread.turns[].items[](userMessage).content[](skill)', reason: 'the live run sent no skill item' },
  // The live run listed threads in the process that had loaded them (idle, systemError).
  { kind: 'result thread/list', path: 'data[].status(notLoaded)', reason: 'the live run listed no thread its process had not loaded' },
]

const covers = (exception: Exception, kind: string, path?: string): boolean => {
  if (exception.kind !== kind) return false
  if (exception.path === undefined) return true
  if (path === undefined) return false
  return path === exception.path || path.startsWith(`${exception.path}.`) || path.startsWith(`${exception.path}[`) || path.startsWith(`${exception.path}(`)
}

/** Each kind and key path of `played` the recordings lack, one line each with where it is played; and the exceptions used. */
function inventedShapes(played: readonly Played[], recorded: Record<string, Shape>, exceptions: readonly Exception[]) {
  const invented: string[] = []
  const used = new Set<Exception>()
  const excused = (kind: string, path?: string): boolean => {
    const exception = exceptions.find((candidate) => covers(candidate, kind, path))
    if (exception !== undefined) used.add(exception)
    return exception !== undefined
  }
  for (const { where, step } of played) {
    const kind = kindOf(step)
    const known = recorded[kind]
    if (known === undefined) {
      if (!excused(kind)) invented.push(`${where}: ${kind} — no recorded message of this kind`)
      continue
    }
    for (const path of Object.keys(shapeOf(bodyOf(step)))) {
      if (known[path] === undefined && !excused(kind, path)) invented.push(`${where}: ${kind} ${path} — no recorded ${kind} has this key`)
    }
  }
  return { invented, used }
}

/** Every step of the fake's scripts, as the fake plays them. */
const fakeSteps = (): Played[] =>
  readdirSync(SCRIPTS)
    .filter((name) => name.endsWith('.jsonl'))
    .sort()
    .flatMap((name) => readSteps(join(SCRIPTS, name), name))

describe('the pinned Codex and its recorded messages', () => {
  it('the recordings are of the pinned Codex, pass its JSON Schema and have every shape the fake plays', () => {
    const recordings = readRecordings(RECORDINGS)
    // Without recordings of this version nothing below means anything: stop here, naming the owner's command.
    expect(versionProblems(recordings, pinnedCodex(), installedCodex())).toEqual([])
    expect.soft(schemaProblems(recordings.steps)).toEqual([])
    expect.soft(hookProblems(readHooks(recordings.folder))).toEqual([])
    const played = fakeSteps()
    expect(played.length).toBeGreaterThan(0)
    const { invented, used } = inventedShapes(played, shapesByKind(recordings.steps), EXCEPTIONS)
    expect.soft(invented).toEqual([])
    expect.soft(EXCEPTIONS.filter((exception) => !used.has(exception)).map(({ kind, path }) => `${kind} ${path ?? ''}: no script needs this exception`)).toEqual([])
  })
})

// --- The checks above on recordings made here: green whatever the recordings folder holds -------------

/** Recordings made of the fake's own scripts: a recording form of every kind and key path the fake plays. */
const fromScripts = (codex: string): Recordings => ({ folder: '/synthetic', manifest: { codex }, steps: fakeSteps() })

describe('the checks of the recordings', () => {
  it('pass recordings of the pinned version that have every shape the fake plays', () => {
    const recordings = fromScripts(pinnedCodex())
    expect(versionProblems(recordings, pinnedCodex(), pinnedCodex())).toEqual([])
    expect(schemaProblems(recordings.steps)).toEqual([])
    expect(inventedShapes(fakeSteps(), shapesByKind(recordings.steps), []).invented).toEqual([])
  })

  it('refuse no recordings and name the owner’s command', () => {
    expect(versionProblems({ folder: DEFAULT_RECORDINGS, manifest: null, steps: [] }, '0.166.0', '0.166.0')).toEqual([
      `no recordings of Codex 0.166.0 in test/fixtures/codex-messages (a manifest.json and *.jsonl): the owner records them with \`${CAPTURE}\` (worfy-multi-vendor ticket 30, done by hand)`,
    ])
    expect(versionProblems({ folder: '/empty', manifest: { codex: '0.166.0' }, steps: [] }, '0.166.0', '0.166.0')).toHaveLength(1)
  })

  it('refuse recordings of another version, a thread of another version and another installed Codex', () => {
    const recordings = fromScripts(pinnedCodex())
    expect(versionProblems({ ...recordings, manifest: { codex: '0.167.0' } }, pinnedCodex(), pinnedCodex())).toEqual([
      `/synthetic/manifest.json: recorded with Codex 0.167.0, package.json pins ${pinnedCodex()}; the owner records them again with \`${CAPTURE}\``,
    ])
    const raised = versionProblems({ ...recordings, manifest: { codex: '0.167.0' } }, '0.167.0', '0.167.0')
    expect(raised.length).toBeGreaterThan(0)
    expect(raised.every((problem) => problem.includes(`a thread of Codex ${pinnedCodex()}, package.json pins 0.167.0`))).toBe(true)
    expect(versionProblems(recordings, pinnedCodex(), '0.1.0')).toEqual([`node_modules has ${PACKAGE} 0.1.0, package.json pins ${pinnedCodex()}; run pnpm install`])
  })

  it('refuse a record the JSON Schema of the pinned Codex refuses, a method it lacks and a wrong answer', () => {
    const bad = (step: Step) => schemaProblems([{ where: 'x.jsonl:1', step }])
    expect(bad({ notify: 'turn/started', params: { threadId: 5, turn: { id: 'u', items: [], status: 'inProgress' } } })).not.toEqual([])
    expect(bad({ notify: 'turn/teleported', params: {} })).toEqual(['x.jsonl:1: turn/teleported is not a notification of the server'])
    expect(bad({ expect: 'thread/start', params: { cwd: 7 }, result: {} })).not.toEqual([])
    expect(bad({ expect: 'account/logout', result: {} })).toEqual([])
    expect(bad({ expect: 'turn/start', error: { message: 'no code' } })).not.toEqual([])
    expect(bad({ request: 'item/fileChange/requestApproval', params: { itemId: 'i', threadId: 't', turnId: 'u', startedAtMs: 1 }, answer: { decision: 'maybe' } })).not.toEqual([])
    expect(bad({ request: 'item/fileChange/requestApproval', params: { itemId: 'i', threadId: 't', turnId: 'u', startedAtMs: 1 }, answer: { decision: 'accept' } })).toEqual([])
  })

  it('name a kind and a key path the fake plays and no recording has, unless an exception lets it through', () => {
    const recorded = shapesByKind(fakeSteps().filter(({ step }) => step.expect !== 'review/start'))
    const review = fakeSteps().filter(({ step }) => step.expect === 'review/start')
    expect(review.length).toBeGreaterThan(0)
    expect(inventedShapes(review, recorded, []).invented).toEqual(review.map(({ where }) => `${where}: result review/start — no recorded message of this kind`))
    const exception = { kind: 'result review/start', reason: 'test' }
    expect(inventedShapes(review, recorded, [exception]).invented).toEqual([])

    const extra: Played = { where: 'y.jsonl:1', step: { notify: 'turn/started', params: { threadId: 't', turn: { id: 'u', items: [], status: 'inProgress', mood: 'cheerful' } } } }
    expect(inventedShapes([extra], recorded, []).invented).toEqual(['y.jsonl:1: notify turn/started turn.mood — no recorded notify turn/started has this key'])
    expect(inventedShapes([extra], recorded, [{ kind: 'notify turn/started', path: 'turn.mood', reason: 'test' }]).invented).toEqual([])
  })
})

describe('the recorded hook inputs and the exceptions', () => {
  const input = (event: string, extra: Record<string, unknown> = {}) => ({ session_id: 's', cwd: '/capture/project', hook_event_name: event, ...extra })
  const complete = { PreToolUse: [input('PreToolUse')], Stop: [input('Stop')], SubagentStop: [input('SubagentStop', { agent_type: 'default' })] }

  it('refuse a missing hook event, an input of another event and a SubagentStop input without agent_type', () => {
    expect(hookProblems(complete)).toEqual([])
    expect(hookProblems({ ...complete, Stop: null })).toEqual(['hooks/Stop.jsonl: no recorded input of Stop'])
    expect(hookProblems({ ...complete, PreToolUse: [] })).toEqual(['hooks/PreToolUse.jsonl: no recorded input of PreToolUse'])
    expect(hookProblems({ ...complete, Stop: [input('Stop'), input('PreToolUse')] })).toEqual(['hooks/Stop.jsonl:2: not an input of Stop'])
    expect(hookProblems({ ...complete, Stop: ['{not json'] })).toEqual(['hooks/Stop.jsonl:1: not an input of Stop'])
    expect(hookProblems({ ...complete, SubagentStop: [input('SubagentStop', { agent_type: 'default' }), input('SubagentStop')] })).toEqual(['hooks/SubagentStop.jsonl:2: no agent_type'])
    expect(hookProblems({ ...complete, SubagentStop: [input('SubagentStop', { agent_type: '' })] })).toEqual(['hooks/SubagentStop.jsonl:1: no agent_type'])
  })

  it('the exceptions let through only their kind and key path: a new key next to one is named', () => {
    const recorded = shapesByKind(readRecordings(DEFAULT_RECORDINGS).steps)
    const next: Played[] = [
      { where: 'z.jsonl:1', step: { notify: 'item/completed', params: { threadId: 't', turnId: 'u', completedAtMs: 1, item: { type: 'mcpToolCall', id: 'm', server: 's', tool: 't', status: 'failed', arguments: {}, result: null, error: { message: 'x', code: 7 } } } } },
      { where: 'z.jsonl:2', step: { request: 'item/commandExecution/requestApproval', params: { threadId: 't', turnId: 'u', itemId: 'i', startedAtMs: 1, reason: 'r', mood: 'cheerful' } } },
      { where: 'z.jsonl:3', step: { notify: 'item/completed', params: { threadId: 't', turnId: 'u', completedAtMs: 1, item: { type: 'agentMessage', id: 'a', text: 'x', mood: 'cheerful' } } } },
    ]
    expect(inventedShapes(next, recorded, EXCEPTIONS).invented).toEqual([
      'z.jsonl:1: notify item/completed item(mcpToolCall).error.code — no recorded notify item/completed has this key',
      'z.jsonl:2: request item/commandExecution/requestApproval mood — no recorded request item/commandExecution/requestApproval has this key',
      'z.jsonl:3: notify item/completed item(agentMessage).mood — no recorded notify item/completed has this key',
    ])
  })
})

describe('the capture script', () => {
  const MAC = 'Alexeys-MacBook-Pro-164.local'

  it('replaces the host name, whole names only, and names one that is left', () => {
    const host = capture.hostReplacements(MAC)
    const status = { notify: 'remoteControl/status/changed', params: { status: 'disabled', serverName: MAC, installationId: null, environmentId: null } }
    expect(capture.scrub(status, host).params.serverName).toBe('capture-host.local')
    expect(capture.scrub(['Alexeys-MacBook-Pro-164 is up', 'see Alexeys-MacBook-Pro-164.local.'], host)).toEqual(['capture-host is up', 'see capture-host.local.'])
    expect(capture.leftovers(JSON.stringify(status), host)).toEqual(['the host name'])
    expect(capture.leftovers(JSON.stringify(capture.scrub(status, host)), host)).toEqual([])

    // A short host name: not a part of a longer word.
    const mac = capture.hostReplacements('mac')
    expect(capture.scrub({ platformOs: 'macos', userAgent: 'worfy (Mac OS 26.6.1)', host: 'mac', at: 'mac.local' }, mac)).toEqual({ platformOs: 'macos', userAgent: 'worfy (Mac OS 26.6.1)', host: 'capture-host', at: 'capture-host.local' })
    expect(capture.leftovers('{"platformOs":"macos","machine":"imac-2"}', mac)).toEqual([])
    expect(capture.leftovers('{"serverName":"mac"}', mac)).toEqual(['the host name'])
    expect(capture.hostReplacements('')).toEqual([])
  })

  it('replaces the installation id, the login id and the host of serverName, and leaves the serverName of an MCP server', () => {
    const steps = [
      { notify: 'remoteControl/status/changed', params: { status: 'disabled', serverName: 'studio.lan', installationId: '6f1c2d3e-0000-4000-8000-0000000000aa', environmentId: null } },
      { expect: 'account/login/start', params: { type: 'chatgpt' }, result: { type: 'chatgpt', loginId: 'a1b2c3d4-0000-4000-8000-0000000000bb', authUrl: 'https://auth.example/x' } },
      { notify: 'account/login/completed', params: { loginId: 'a1b2c3d4-0000-4000-8000-0000000000bb', success: true, error: null } },
      { request: 'mcpServer/elicitation/request', params: { serverName: 'capture', message: 'on studio.lan' } },
    ]
    const replacements = capture.identifierReplacements(steps)
    expect(capture.scrub(steps, replacements)).toEqual([
      { notify: 'remoteControl/status/changed', params: { status: 'disabled', serverName: 'capture-host.local', installationId: '00000000-0000-4000-8000-000000000001', environmentId: null } },
      { expect: 'account/login/start', params: { type: 'chatgpt' }, result: { type: 'chatgpt', loginId: '00000000-0000-4000-8000-000000000002', authUrl: 'https://auth.example/x' } },
      { notify: 'account/login/completed', params: { loginId: '00000000-0000-4000-8000-000000000002', success: true, error: null } },
      { request: 'mcpServer/elicitation/request', params: { serverName: 'capture', message: 'on capture-host.local' } },
    ])
    expect(new Set(capture.leftovers(JSON.stringify(steps), replacements))).toEqual(new Set(['the installation id', 'the login id', 'the host name']))
    expect(capture.leftovers(JSON.stringify(capture.scrub(steps, replacements)), replacements)).toEqual([])
  })

  it('a run replaces its folders, the home folder, the host name, the identifiers and the secrets of the login', () => {
    const steps = [
      { notify: 'remoteControl/status/changed', params: { status: 'disabled', serverName: 'studio.lan', installationId: 'inst-7', environmentId: null } },
      { notify: 'account/login/completed', params: { loginId: 'login-9', success: true, error: null } },
    ]
    const replacements = capture.replacementsOf({
      project: '/nowhere/worfy-capture-1/project',
      codexHome: '/nowhere/worfy-capture-1/codex-home',
      work: '/nowhere/worfy-capture-1',
      home: '/Users/someone',
      host: MAC,
      steps,
      secrets: [{ from: 'someone@example.org', to: 'owner@example.com', what: 'the email' }],
    })
    const recorded = [
      ...steps,
      { notify: 'warning', params: { threadId: 't', message: `${MAC}: /nowhere/worfy-capture-1/codex-home/hooks.json, /nowhere/worfy-capture-1/project, /nowhere/worfy-capture-1/x, /Users/someone/.zshrc, someone@example.org` } },
    ]
    const text = JSON.stringify(recorded)
    expect(new Set(capture.leftovers(text, replacements))).toEqual(new Set(['the CODEX_HOME folder', 'the Project folder', 'the temporary folder', 'the home folder', 'the host name', 'the installation id', 'the login id', 'the email']))
    const scrubbed = capture.scrub(recorded, replacements)
    expect(capture.leftovers(JSON.stringify(scrubbed), replacements)).toEqual([])
    expect(scrubbed[2]).toEqual({ notify: 'warning', params: { threadId: 't', message: 'capture-host.local: /capture/codex-home/hooks.json, /capture/project, /capture/x, /home/owner/.zshrc, owner@example.com' } })
  })

  it('the committed recordings carry the values the script writes in their place', () => {
    const steps = readRecordings(DEFAULT_RECORDINGS).steps.map(({ step }) => step)
    const replacements = capture.identifierReplacements(steps)
    expect(new Set(replacements.map(({ to }) => to))).toEqual(new Set(['00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000002', 'capture-host.local', 'capture-host']))
    expect(capture.scrub(steps, replacements)).toEqual(steps)
  })

  it('refuses under VITEST before it reads its arguments, --help too', async () => {
    // Without VITEST the calls below could reach the real Codex: they never run then.
    expect(process.env.VITEST).toBeTruthy()
    if (!process.env.VITEST) return
    expect(await capture.main(['--help'])).toBe(2)
    expect(await capture.main(['--no-such-flag'])).toBe(2)
  })
})
